/**
 * Get the default size of a BPMN element.
 *
 * Elements without an explicit default, e.g. `bpmn:CallActivity`, fall back to
 * `DEFAULT_SIZE`.
 *
 * @param element The element.
 * @param di The DI; defaults to the DI of the element.
 *
 * @return Default width and height of the element.
 */
export function getDefaultSize(element: Element, di?: ModdleElement): Dimensions;

/**
 * Get the default size of a BPMN element.
 *
 * Elements without an explicit default, e.g. `bpmn:CallActivity`, fall back to
 * `DEFAULT_SIZE`.
 *
 * @param element The element.
 * @param di The DI.
 *
 * @return Default width and height of the element.
 */
export function getDefaultSize(element: ModdleElement, di: ModdleElement): Dimensions;

/**
 * Default size of elements without an explicit default.
 *
 */
export const DEFAULT_SIZE: Dimensions;

export const DEFAULT_TASK_SIZE: Dimensions;
export const DEFAULT_GATEWAY_SIZE: Dimensions;
export const DEFAULT_EVENT_SIZE: Dimensions;
export const DEFAULT_SUB_PROCESS_SIZE: Dimensions;
export const DEFAULT_COLLAPSED_SUB_PROCESS_SIZE: Dimensions;
export const DEFAULT_PARTICIPANT_SIZE: Dimensions;
export const DEFAULT_VERTICAL_PARTICIPANT_SIZE: Dimensions;
export const DEFAULT_COLLAPSED_PARTICIPANT_SIZE: Dimensions;
export const DEFAULT_VERTICAL_COLLAPSED_PARTICIPANT_SIZE: Dimensions;
export const DEFAULT_LANE_SIZE: Dimensions;
export const DEFAULT_DATA_OBJECT_REFERENCE_SIZE: Dimensions;
export const DEFAULT_DATA_STORE_REFERENCE_SIZE: Dimensions;
export const DEFAULT_TEXT_ANNOTATION_SIZE: Dimensions;
export const DEFAULT_GROUP_SIZE: Dimensions;
type Dimensions = import("diagram-js/lib/util/Types").Dimensions;
type Element = import("../model/Types").Element;
type ModdleElement = import("../model/Types").ModdleElement;